    : '最近一次：${_fmtTime(at)}（${_kindLabel[kind] ?? kind ?? '未记录'}）。本机只记录时间与方式，不保存文件路径与内容。';

final summary = at == 0
    ? context.tr(AppStrings.backupNever)
    : context.trf(AppStrings.backupLast, {'time': _fmtTime(at), 'kind': _kindLabel(context, kind)});
